CREATE TABLE IF NOT EXISTS lattis_paynow_payment (external_id char(36) PRIMARY KEY, amount_minor bigint NOT NULL CHECK (amount_minor BETWEEN 100 AND 100000000), currency char(3) NOT NULL CHECK (currency = 'PLN'), description varchar(255) NOT NULL, buyer_email_sealed varchar(256) NOT NULL, created_by varchar(191) NOT NULL, paynow_payment_id varchar(16) NULL, redirect_url text NULL, status varchar(20) NOT NULL CHECK (status IN ('QUEUED','UNKNOWN','BLOCKED','NEW','PENDING','CONFIRMED','REJECTED','ERROR','EXPIRED','ABANDONED')), provider_modified_at datetime(3) NULL, attempt_count int NOT NULL DEFAULT 0, next_attempt_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), last_error varchar(100) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY lattis_paynow_payment_provider_id (paynow_payment_id), KEY lattis_paynow_payment_due (next_attempt_at,status));
